-- Live tracking RPCs aligned with Shadow schema.
CREATE OR REPLACE FUNCTION public.update_driver_live_location(p_latitude double precision,p_longitude double precision,p_accuracy_m double precision DEFAULT NULL,p_heading double precision DEFAULT NULL,p_speed_kmh double precision DEFAULT NULL,p_captured_at timestamptz DEFAULT now()) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_driver_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF; IF p_latitude IS NULL OR p_longitude IS NULL OR p_latitude NOT BETWEEN -90 AND 90 OR p_longitude NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'INVALID_COORDINATES'; END IF; SELECT d.driver_id INTO v_driver_id FROM public.drivers d WHERE d.auth_user_id=auth.uid() AND d.is_active=true LIMIT 1; IF v_driver_id IS NULL THEN RAISE EXCEPTION 'DRIVER_ACCOUNT_NOT_LINKED'; END IF; IF NOT EXISTS (SELECT 1 FROM public.driver_vehicle_assignments dva JOIN public.vehicles v ON v.vehicle_id=dva.vehicle_id AND v.is_active=true WHERE dva.driver_id=v_driver_id AND dva.ended_at IS NULL) THEN RAISE EXCEPTION 'NO_ACTIVE_VEHICLE_ASSIGNMENT'; END IF; INSERT INTO public.driver_live_locations(driver_id,latitude,longitude,accuracy_m,captured_at,received_at) VALUES(v_driver_id,p_latitude,p_longitude,p_accuracy_m,COALESCE(p_captured_at,now()),now()) ON CONFLICT(driver_id) DO UPDATE SET latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,accuracy_m=EXCLUDED.accuracy_m,captured_at=EXCLUDED.captured_at,received_at=now(); RETURN jsonb_build_object('success',true,'driver_id',v_driver_id,'received_at',now()); END; $$;
CREATE OR REPLACE FUNCTION public.get_vehicle_live_locations() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_auth_user_id uuid := auth.uid(); BEGIN IF v_auth_user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF; IF NOT EXISTS (SELECT 1 FROM public.app_users au WHERE au.auth_user_id=v_auth_user_id AND au.is_active=true AND upper(au.role) IN ('ADMIN','HEAD_OFFICE')) THEN RAISE EXCEPTION 'INSUFFICIENT_ROLE'; END IF; RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('driver_id',d.driver_id,'driver_name',d.name,'vehicle_id',v.vehicle_id,'plate_number',v.plate_number,'vehicle_code',v.vehicle_code,'latitude',loc.latitude,'longitude',loc.longitude,'accuracy_m',loc.accuracy_m,'captured_at',loc.captured_at,'updated_at',loc.received_at,'is_stale',loc.received_at < now()-interval '10 minutes') ORDER BY loc.received_at DESC) FROM public.driver_live_locations loc JOIN public.drivers d ON d.driver_id=loc.driver_id AND d.is_active=true JOIN LATERAL (SELECT dva.vehicle_id FROM public.driver_vehicle_assignments dva JOIN public.vehicles va ON va.vehicle_id=dva.vehicle_id AND va.is_active=true WHERE dva.driver_id=d.driver_id AND dva.ended_at IS NULL ORDER BY dva.assigned_at DESC LIMIT 1) active_assignment ON true JOIN public.vehicles v ON v.vehicle_id=active_assignment.vehicle_id),'[]'::jsonb); END; $$;
REVOKE ALL ON FUNCTION public.update_driver_live_location(double precision,double precision,double precision,double precision,double precision,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_driver_live_location(double precision,double precision,double precision,double precision,double precision,timestamptz) TO authenticated;
REVOKE ALL ON FUNCTION public.get_vehicle_live_locations() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_vehicle_live_locations() TO authenticated;
NOTIFY pgrst, 'reload schema';
